def merge_busy(intervals):
    import heapq
    from collections import defaultdict

    if not intervals:
        return []

    starts = defaultdict(list)
    ends = defaultdict(list)
    coords = set()

    for start, end, prio in intervals:
        starts[start].append(prio)
        ends[end].append(prio)
        coords.add(start)
        coords.add(end)

    active = defaultdict(int)
    heap = []

    def add_prio(prio):
        active[prio] += 1
        heapq.heappush(heap, -prio)

    def remove_prio(prio):
        active[prio] -= 1
        if active[prio] <= 0:
            del active[prio]

    def clean_heap():
        while heap and active.get(-heap[0], 0) <= 0:
            heapq.heappop(heap)

    result = []
    prev = None

    for x in sorted(coords):
        if prev is not None and prev < x:
            clean_heap()
            if heap:
                prio = -heap[0]
                if result and result[-1][1] == prev and result[-1][2] == prio:
                    result[-1] = (result[-1][0], x, prio)
                else:
                    result.append((prev, x, prio))

        for prio in ends.get(x, ()):
            remove_prio(prio)
        for prio in starts.get(x, ()):
            add_prio(prio)

        prev = x

    return result

class TokenBucket:
    def __init__(self, capacity: float, refill_rate: float) -> None:
        self.capacity = float(capacity)
        self.refill_rate = float(refill_rate)
        self._tokens = float(capacity)
        self._last_now = None

    def allow(self, n: float = 1.0, now: float = 0.0) -> bool:
        n = float(n)
        now = float(now)

        if self._last_now is None:
            self._last_now = now
        else:
            elapsed = now - self._last_now
            if elapsed > 0.0:
                self._tokens = min(self.capacity, self._tokens + elapsed * self.refill_rate)
            self._last_now = now

        if n <= 0.0:
            return True

        if self._tokens >= n:
            self._tokens -= n
            return True

        return False

