def parse_statement(text):
    import re
    from datetime import date

    month_map = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
        "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    }

    def parse_date(raw):
        s = raw.strip()

        m = re.fullmatch(r"(\d{1,2})/(\d{1,2})/(\d{4})", s)
        if m:
            d = int(m.group(1))
            mo = int(m.group(2))
            y = int(m.group(3))
            try:
                date(y, mo, d)
            except ValueError:
                return None
            return f"{y:04d}-{mo:02d}-{d:02d}"

        m = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})", s)
        if m:
            y = int(m.group(1))
            mo = int(m.group(2))
            d = int(m.group(3))
            try:
                date(y, mo, d)
            except ValueError:
                return None
            return f"{y:04d}-{mo:02d}-{d:02d}"

        m = re.fullmatch(r"(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})", s)
        if m:
            mo = month_map.get(m.group(2).lower())
            if mo is None:
                return None
            d = int(m.group(1))
            y = int(m.group(3))
            try:
                date(y, mo, d)
            except ValueError:
                return None
            return f"{y:04d}-{mo:02d}-{d:02d}"

        return None

    def parse_amount(raw):
        s = raw.strip()
        if not s:
            return None

        negative = False

        if re.search(r"\s*DR$", s, re.IGNORECASE):
            negative = True
            s = re.sub(r"\s*DR$", "", s, flags=re.IGNORECASE).strip()

        currency_count = 0
        paren_count = 0
        changed = True

        while changed:
            changed = False
            s = s.strip()

            if s.startswith("(") and s.endswith(")"):
                paren_count += 1
                if paren_count > 1:
                    return None
                negative = True
                s = s[1:-1].strip()
                changed = True
            elif s and s[0] in "₹$":
                currency_count += 1
                if currency_count > 1:
                    return None
                s = s[1:].strip()
                changed = True

        if not re.fullmatch(r"\d+(?:,\d+)*(?:\.\d+)?", s):
            return None

        try:
            value = float(s.replace(",", ""))
        except (ValueError, OverflowError):
            return None

        if negative:
            value = -value
        if value == 0.0:
            value = 0.0

        return value

    records = []

    for idx, line in enumerate(text.splitlines()):
        if not line.strip():
            continue

        parts = line.split(",", 2)
        if len(parts) != 3:
            continue

        parsed_date = parse_date(parts[0])
        if parsed_date is None:
            continue

        parsed_amount = parse_amount(parts[2])
        if parsed_amount is None:
            continue

        records.append((parsed_date, idx, parts[1].strip(), parsed_amount))

    records.sort(key=lambda item: (item[0], item[1]))

    return [
        {"date": item[0], "description": item[2], "amount": item[3]}
        for item in records
    ]

def parse_statement(text):
    import re
    from datetime import date

    if not isinstance(text, str):
        return []

    month_names = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
        "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    }

    number_re = re.compile(r"(?:\d+(?:,\d+)*(?:\.\d+)?|\.\d+)")
    dr_re = re.compile(r"(.*?)\s*DR", re.IGNORECASE)
    currency_re = re.compile(r"^[₹$]\s*")
    iso_re = re.compile(r"(\d{4})-(\d{1,2})-(\d{1,2})")
    slash_re = re.compile(r"(\d{1,2})/(\d{1,2})/(\d{4})")
    month_re = re.compile(
        r"(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{4})",
        re.IGNORECASE,
    )

    def parse_date(value):
        value = value.strip()

        m = iso_re.fullmatch(value)
        if m:
            y, mo, d = map(int, m.groups())
            try:
                return date(y, mo, d).isoformat()
            except ValueError:
                return None

        m = slash_re.fullmatch(value)
        if m:
            d, mo, y = map(int, m.groups())
            try:
                return date(y, mo, d).isoformat()
            except ValueError:
                return None

        m = month_re.fullmatch(value)
        if m:
            d = int(m.group(1))
            mo = month_names[m.group(2).lower()]
            y = int(m.group(3))
            try:
                return date(y, mo, d).isoformat()
            except ValueError:
                return None

        return None

    def strip_dr(value):
        m = dr_re.fullmatch(value)
        if m:
            return m.group(1).strip(), True
        return value, False

    def parse_amount(value):
        value = value.strip()
        if not value:
            return None

        negative = False

        value, dr = strip_dr(value)
        if dr:
            negative = True

        value = currency_re.sub("", value.strip())

        if value.startswith("(") and value.endswith(")"):
            negative = True
            value = value[1:-1].strip()
            value = currency_re.sub("", value.strip())

            value, dr = strip_dr(value)
            if dr:
                negative = True

        if not number_re.fullmatch(value):
            return None

        try:
            amount = float(value.replace(",", ""))
        except ValueError:
            return None

        if negative and amount != 0.0:
            amount = -amount

        return amount

    records = []

    for idx, line in enumerate(text.splitlines()):
        line = line.strip()
        if not line:
            continue

        parts = line.split(",", 2)
        if len(parts) != 3:
            continue

        date_str, desc_str, amount_str = parts

        parsed_date = parse_date(date_str)
        parsed_amount = parse_amount(amount_str)

        if parsed_date is None or parsed_amount is None:
            continue

        records.append((
            idx,
            {
                "date": parsed_date,
                "description": desc_str.strip(),
                "amount": parsed_amount,
            },
        ))

    records.sort(key=lambda item: (item[1]["date"], item[0]))

    return [item[1] for item in records]

