def parse_statement(text):
    import re

    month_map = {
        'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
        'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
    }

    dmy_re = re.compile(r'^([0-9]{1,2})/([0-9]{1,2})/([0-9]{4})$')
    ymd_re = re.compile(r'^([0-9]{4})-([0-9]{1,2})-([0-9]{1,2})$')
    mon_re = re.compile(
        r'^([0-9]{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+([0-9]{4})$'
    )
    dr_re = re.compile(r'^(.*?)\s+DR$')
    num_re = re.compile(
        r'^(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+|[0-9]{1,2}(?:,[0-9]{2})+,[0-9]{3})(?:\.[0-9]+)?$'
    )

    def valid_date(y, m, d):
        if y < 1 or y > 9999:
            return False
        if m < 1 or m > 12:
            return False
        if d < 1:
            return False
        leap = (y % 4 == 0) and (y % 100 != 0 or y % 400 == 0)
        days_in_month = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return d <= days_in_month[m - 1]

    def normalize_date(s):
        s = s.strip()

        m = dmy_re.match(s)
        if m:
            d = int(m.group(1))
            mo = int(m.group(2))
            y = int(m.group(3))
            if valid_date(y, mo, d):
                return f'{y:04d}-{mo:02d}-{d:02d}'
            return None

        m = ymd_re.match(s)
        if m:
            y = int(m.group(1))
            mo = int(m.group(2))
            d = int(m.group(3))
            if valid_date(y, mo, d):
                return f'{y:04d}-{mo:02d}-{d:02d}'
            return None

        m = mon_re.match(s)
        if m:
            d = int(m.group(1))
            mo = month_map[m.group(2)]
            y = int(m.group(3))
            if valid_date(y, mo, d):
                return f'{y:04d}-{mo:02d}-{d:02d}'

        return None

    def strip_currency(s):
        s = s.strip()
        if s.startswith('\u20b9') or s.startswith('$'):
            s = s[1:].lstrip()
        return s

    def parse_amount(s):
        s = s.strip()
        if not s:
            return None

        negative = False
        s = strip_currency(s)
        if not s:
            return None

        if s.startswith('(') and s.endswith(')'):
            negative = True
            s = strip_currency(s[1:-1])
        else:
            m = dr_re.match(s)
            if m:
                negative = True
                s = strip_currency(m.group(1))

        if not s or not num_re.match(s):
            return None

        try:
            value = float(s.replace(',', ''))
        except (ValueError, OverflowError):
            return None

        return -value if negative else value

    records = []
    for idx, raw_line in enumerate(text.splitlines()):
        line = raw_line.strip()
        if not line:
            continue

        parts = line.split(',', 2)
        if len(parts) != 3:
            continue

        date_iso = normalize_date(parts[0])
        if date_iso is None:
            continue

        amount = parse_amount(parts[2])
        if amount is None:
            continue

        records.append((date_iso, idx, parts[1].strip(), amount))

    records.sort(key=lambda item: (item[0], item[1]))
    return [
        {'date': date_iso, 'description': description, 'amount': amount}
        for date_iso, _, description, amount in records
    ]

def rotation_index(a):
    if not a:
        return -1
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] > a[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo

