def merge_busy2(intervals, cancels):
    import heapq
    from collections import defaultdict

    if not intervals:
        return []

    starts = defaultdict(list)
    ends = defaultdict(list)
    cancel_starts = defaultdict(int)
    cancel_ends = defaultdict(int)
    coords = set()

    for start, end, prio in intervals:
        starts[start].append(prio)
        ends[end].append(prio)
        coords.add(start)
        coords.add(end)

    if cancels is not None:
        for start, end in cancels:
            cancel_starts[start] += 1
            cancel_ends[end] += 1
            coords.add(start)
            coords.add(end)

    active = {}
    heap = []
    cancel_active = 0
    prev = None
    result = []

    for x in sorted(coords):
        if prev is not None and prev < x:
            while heap and active.get(-heap[0], 0) <= 0:
                heapq.heappop(heap)

            if cancel_active == 0 and heap:
                prio = -heap[0]
                if result and result[-1][1] == prev and result[-1][2] == prio:
                    result[-1] = (result[-1][0], x, prio)
                else:
                    result.append((prev, x, prio))

        for prio in ends.get(x, ()):
            active[prio] = active.get(prio, 0) - 1

        for prio in starts.get(x, ()):
            active[prio] = active.get(prio, 0) + 1
            heapq.heappush(heap, -prio)

        cancel_active += cancel_starts.get(x, 0) - cancel_ends.get(x, 0)
        prev = x

    return result

def merge_busy2(intervals, cancels):
    import heapq

    if not intervals:
        return []

    events = {}
    for s, e, p in intervals:
        events.setdefault(s, []).append((1, p))
        events.setdefault(e, []).append((-1, p))

    if cancels is not None:
        for s, e in cancels:
            events.setdefault(s, []).append((2, None))
            events.setdefault(e, []).append((-2, None))

    coords = sorted(events)
    if len(coords) < 2:
        return []

    active = {}
    heap = []
    cancel_active = 0
    result = []

    def current_max():
        while heap and active.get(-heap[0], 0) <= 0:
            heapq.heappop(heap)
        return -heap[0] if heap else None

    for i in range(len(coords) - 1):
        x = coords[i]

        for kind, p in events[x]:
            if kind == 2:
                cancel_active += 1
            elif kind == -2:
                cancel_active -= 1
            else:
                before = active.get(p, 0)
                after = before + kind
                active[p] = after
                if after > 0 and before <= 0:
                    heapq.heappush(heap, -p)

        if cancel_active == 0:
            p = current_max()
            if p is not None:
                end = coords[i + 1]
                if result and result[-1][1] == x and result[-1][2] == p:
                    result[-1] = (result[-1][0], end, p)
                else:
                    result.append((x, end, p))

    return result

def merge_busy2(intervals, cancels):
    import heapq

    starts = {}
    cancel_delta = {}
    coords = set()

    for start, end, prio in intervals:
        starts.setdefault(start, []).append((prio, end))
        coords.add(start)
        coords.add(end)

    for start, end in cancels:
        cancel_delta[start] = cancel_delta.get(start, 0) + 1
        cancel_delta[end] = cancel_delta.get(end, 0) - 1
        coords.add(start)
        coords.add(end)

    if not coords:
        return []

    points = sorted(coords)
    heap = []
    cancel_count = 0
    result = []

    for i in range(len(points) - 1):
        x = points[i]
        next_x = points[i + 1]

        for prio, end in starts.get(x, ()):
            heapq.heappush(heap, (-prio, end))

        while heap and heap[0][1] <= x:
            heapq.heappop(heap)

        cancel_count += cancel_delta.get(x, 0)

        if cancel_count == 0 and heap:
            prio = -heap[0][0]
            if result and result[-1][1] == x and result[-1][2] == prio:
                result[-1] = (result[-1][0], next_x, prio)
            else:
                result.append((x, next_x, prio))

    return result

def merge_busy2(intervals, cancels):
    import heapq

    starts = {}
    ends = {}
    coords = set()

    if intervals is not None:
        for s, e, p in intervals:
            if s >= e:
                continue
            starts.setdefault(s, []).append(p)
            ends.setdefault(e, []).append(p)
            coords.add(s)
            coords.add(e)

    if not coords:
        return []

    resolved = []

    def emit_resolved(s, e, p):
        if s >= e:
            return
        if resolved and resolved[-1][1] == s and resolved[-1][2] == p:
            resolved[-1] = (resolved[-1][0], e, p)
        else:
            resolved.append((s, e, p))

    heap = []
    active = {}
    sorted_coords = sorted(coords)

    for i in range(len(sorted_coords) - 1):
        x = sorted_coords[i]
        nx = sorted_coords[i + 1]

        for p in ends.get(x, ()):
            cnt = active.get(p, 0) - 1
            if cnt > 0:
                active[p] = cnt
            else:
                active.pop(p, None)

        for p in starts.get(x, ()):
            active[p] = active.get(p, 0) + 1
            heapq.heappush(heap, -p)

        while heap and active.get(-heap[0], 0) <= 0:
            heapq.heappop(heap)

        if heap:
            emit_resolved(x, nx, -heap[0])

    if cancels is None:
        return resolved

    clean = []
    for s, e in cancels:
        if s < e:
            clean.append((s, e))

    if not clean:
        return resolved

    clean.sort()
    merged = []
    for s, e in clean:
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        elif e > merged[-1][1]:
            merged[-1][1] = e

    result = []

    def emit_result(s, e, p):
        if s >= e:
            return
        if result and result[-1][1] == s and result[-1][2] == p:
            result[-1] = (result[-1][0], e, p)
        else:
            result.append((s, e, p))

    j = 0
    m = len(merged)

    for s, e, p in resolved:
        while j < m and merged[j][1] <= s:
            j += 1

        cur = s
        k = j

        while k < m and merged[k][0] < e:
            cs, ce = merged[k]
            if ce <= cur:
                k += 1
                continue
            if cur < cs:
                emit_result(cur, min(cs, e), p)
            if ce > cur:
                cur = ce
            if cur >= e:
                break
            k += 1

        if cur < e:
            emit_result(cur, e, p)

    return result

class RateTree:
    def __init__(self, spec):
        self._nodes = {}
        for name, (capacity, refill_rate, parent) in spec.items():
            self._nodes[name] = {
                "capacity": capacity,
                "rate": refill_rate,
                "parent": parent,
                "tokens": capacity,
                "last": None,
            }
        self._path_cache = {}

    def _path_for(self, name):
        path = self._path_cache.get(name)
        if path is None:
            path = []
            seen = set()
            current = name

            while current is not None and current not in seen:
                node = self._nodes.get(current)
                if node is None:
                    break
                seen.add(current)
                path.append(current)
                current = node["parent"]

            path = tuple(path)
            self._path_cache[name] = path

        return path

    def _touch(self, node, now):
        last = node["last"]

        if last is None:
            node["last"] = now
            return

        if now > last:
            elapsed = now - last
            if elapsed > 0.0:
                node["tokens"] = min(
                    node["capacity"],
                    node["tokens"] + elapsed * node["rate"],
                )
            node["last"] = now

    def allow(self, name, n=1.0, now=0.0):
        if name not in self._nodes:
            return False
        if not (n >= 0.0):
            return False

        path = self._path_for(name)
        if not path:
            return False

        nodes = self._nodes

        for node_name in path:
            self._touch(nodes[node_name], now)

        for node_name in path:
            if nodes[node_name]["tokens"] < n:
                return False

        for node_name in path:
            nodes[node_name]["tokens"] -= n

        return True

class RateTree:
    _EPS = 1e-12
    _INF = float("inf")

    def __init__(self, spec):
        self._capacity = {}
        self._rate = {}
        self._parent = {}
        self._tokens = {}
        self._last = {}

        for name, (capacity, refill_rate, parent) in spec.items():
            capacity = float(capacity)
            refill_rate = float(refill_rate)

            self._capacity[name] = capacity
            self._rate[name] = refill_rate
            self._parent[name] = parent
            self._tokens[name] = capacity
            self._last[name] = None

        self._paths = {}

    def _path(self, name):
        path = self._paths.get(name)
        if path is not None:
            return path

        if name not in self._parent:
            return None

        path = []
        cur = name
        seen = set()

        while cur is not None:
            if cur in seen or cur not in self._parent:
                return None
            seen.add(cur)
            path.append(cur)
            cur = self._parent[cur]

        self._paths[name] = path
        return path

    def allow(self, name, n=1.0, now=0.0):
        path = self._path(name)
        if path is None:
            return False

        n = float(n)
        now = float(now)

        if n != n or now != now or n < 0.0 or n == self._INF:
            return False

        for node in path:
            last = self._last[node]

            if last is None:
                self._last[node] = now
                self._tokens[node] = self._capacity[node]
            elif now > last:
                elapsed = now - last
                rate = self._rate[node]
                tokens = self._tokens[node]

                if rate > 0.0:
                    tokens += elapsed * rate

                if tokens < 0.0:
                    tokens = 0.0

                capacity = self._capacity[node]
                if tokens > capacity:
                    tokens = capacity

                self._tokens[node] = tokens
                self._last[node] = now

        for node in path:
            if n > self._capacity[node] or self._tokens[node] + self._EPS < n:
                return False

        for node in path:
            tokens = self._tokens[node] - n

            if tokens < 0.0 and tokens > -self._EPS:
                tokens = 0.0

            capacity = self._capacity[node]
            if tokens > capacity:
                tokens = capacity

            self._tokens[node] = tokens

        return True

class RateTree:
    def __init__(self, spec):
        self._capacity = {}
        self._rate = {}
        self._parent = {}
        self._tokens = {}
        self._last = {}

        for name, (capacity, refill_rate, parent) in spec.items():
            capacity = float(capacity)
            refill_rate = float(refill_rate)
            self._capacity[name] = capacity
            self._rate[name] = refill_rate
            self._parent[name] = parent
            self._tokens[name] = capacity
            self._last[name] = None

        self._paths = {}
        for name in self._capacity:
            path = []
            cur = name
            seen = set()
            while cur is not None and cur in self._parent and cur not in seen:
                seen.add(cur)
                path.append(cur)
                cur = self._parent[cur]
            self._paths[name] = tuple(path)

    def _update(self, name, now):
        last = self._last[name]
        if last is None:
            self._last[name] = now
            return

        if now <= last:
            return

        elapsed = now - last
        self._last[name] = now

        rate = self._rate[name]
        if elapsed > 0.0 and rate != 0.0:
            tokens = self._tokens[name] + elapsed * rate
            capacity = self._capacity[name]
            if tokens > capacity:
                tokens = capacity
            self._tokens[name] = tokens

    def allow(self, name, n=1.0, now=0.0):
        path = self._paths.get(name)
        if path is None:
            return False

        if not (0.0 <= n < float("inf")):
            return False

        if now is None or now != now:
            return False

        for node in path:
            self._update(node, now)

        tol = 1e-12 * abs(n) + 1e-18

        for node in path:
            if n > self._capacity[node]:
                return False
            tokens = self._tokens[node]
            if tokens < n and n - tokens > tol:
                return False

        for node in path:
            tokens = self._tokens[node] - n
            if tokens < 0.0:
                tokens = 0.0
            self._tokens[node] = tokens

        return True

class RateTree:
    def __init__(self, spec):
        self._nodes = {}
        roots = 0

        for name, (capacity, refill_rate, parent) in spec.items():
            capacity = float(capacity)
            refill_rate = float(refill_rate)

            self._nodes[name] = {
                "capacity": capacity,
                "rate": refill_rate,
                "parent": parent,
                "tokens": capacity,
                "last": None,
            }

            if parent is None:
                roots += 1

        if roots != 1:
            raise ValueError("spec must contain exactly one root")

        for info in self._nodes.values():
            parent = info["parent"]
            if parent is not None and parent not in self._nodes:
                raise ValueError("parent references an unknown node")

        self._paths = {}
        for name in self._nodes:
            path = []
            cur = name
            seen = set()

            while cur is not None:
                if cur in seen or cur not in self._nodes:
                    raise ValueError("invalid parent chain")
                seen.add(cur)
                path.append(cur)
                cur = self._nodes[cur]["parent"]

            self._paths[name] = tuple(path)

    def allow(self, name: str, n: float = 1.0, now: float = 0.0) -> bool:
        n = float(n)
        now = float(now)

        if not (n >= 0.0):
            return False

        path = self._paths.get(name)
        if path is None:
            return False

        for node_name in path:
            info = self._nodes[node_name]
            last = info["last"]

            if last is not None:
                elapsed = now - last
                if elapsed > 0.0:
                    tokens = info["tokens"] + elapsed * info["rate"]
                    capacity = info["capacity"]
                    if tokens > capacity:
                        tokens = capacity
                    info["tokens"] = tokens

            info["last"] = now

        for node_name in path:
            if self._nodes[node_name]["tokens"] < n:
                return False

        for node_name in path:
            self._nodes[node_name]["tokens"] -= n

        return True

def parse_ledger(text):
    import re
    from datetime import date

    if not isinstance(text, str):
        return []

    MONTHS = {
        'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
        'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
    }
    mon = '|'.join(MONTHS)
    date_re = re.compile(
        r'^\s*(?:'
        r'(?P<d1>\d{1,2})/(?P<m1>\d{1,2})/(?P<y1>\d{4})'
        r'|(?P<y2>\d{4})-(?P<m2>\d{1,2})-(?P<d2>\d{1,2})'
        r'|(?P<d3>\d{1,2})\s+(?P<mon3>' + mon + r')\s+(?P<y3>\d{4})'
        r'|(?P<mon4>' + mon + r')\s+(?P<d4>\d{1,2})\s*,\s*(?P<y4>\d{4})'
        r')'
    )
    dr_re = re.compile(r'(?P<body>.*?)\s+DR')
    num_re = re.compile(
        r'(?:\d{1,3}(?:,\d{3})*|\d{1,3}(?:,\d{2,3}){2,}|\d+)(?:\.\d+)?'
    )
    symbols = {'₹', '$', '€'}
    rates = {'INR': 1.0, 'USD': 83.5, 'EUR': 90.25}
    inf = float('inf')

    def normalize_date(match):
        try:
            if match.group('d1') is not None:
                day = int(match.group('d1'))
                month = int(match.group('m1'))
                year = int(match.group('y1'))
            elif match.group('y2') is not None:
                year = int(match.group('y2'))
                month = int(match.group('m2'))
                day = int(match.group('d2'))
            elif match.group('d3') is not None:
                day = int(match.group('d3'))
                month = MONTHS[match.group('mon3')]
                year = int(match.group('y3'))
            else:
                month = MONTHS[match.group('mon4')]
                day = int(match.group('d4'))
                year = int(match.group('y4'))
            date(year, month, day)
            return f'{year:04d}-{month:02d}-{day:02d}'
        except Exception:
            return None

    def parse_amount(raw):
        t = raw.strip()
        if not t:
            return None

        negative = False
        dr_match = dr_re.fullmatch(t)
        if dr_match:
            negative = True
            t = dr_match.group('body').strip()

        if t.startswith('(') and t.endswith(')'):
            negative = True
            t = t[1:-1].strip()
        if t and t[0] in symbols:
            t = t[1:].lstrip()
        while t.startswith('(') and t.endswith(')'):
            negative = True
            t = t[1:-1].strip()

        if not t:
            return None
        if not num_re.fullmatch(t):
            return None
        try:
            value = float(t.replace(',', ''))
        except (ValueError, OverflowError):
            return None
        if value != value or value == inf or value == -inf:
            return None
        if negative:
            value = -value
        if value == 0:
            value = 0.0
        return value

    parsed = []
    seen = set()

    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        if s.startswith('\ufeff'):
            s = s[1:]

        date_match = date_re.match(s)
        if not date_match:
            continue
        iso_date = normalize_date(date_match)
        if iso_date is None:
            continue

        rest = s[date_match.end():].lstrip()
        if not rest.startswith(','):
            continue
        rest = rest[1:]

        i = 0
        while i < len(rest) and rest[i].isspace():
            i += 1

        if i < len(rest) and rest[i] == '"':
            chars = []
            i += 1
            closed = False
            while i < len(rest):
                ch = rest[i]
                if ch == '"':
                    if i + 1 < len(rest) and rest[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                else:
                    chars.append(ch)
                    i += 1
            if not closed:
                continue
            description = ''.join(chars).strip()
            while i < len(rest) and rest[i].isspace():
                i += 1
            if i >= len(rest) or rest[i] != ',':
                continue
            rest = rest[i + 1:]
        else:
            comma_pos = rest.find(',')
            if comma_pos == -1:
                continue
            description = rest[:comma_pos].strip()
            rest = rest[comma_pos + 1:]

        if ',' not in rest:
            continue
        amount_raw, currency_raw = rest.rsplit(',', 1)
        currency = currency_raw.strip()
        if currency not in rates:
            continue

        amount = parse_amount(amount_raw)
        if amount is None:
            continue

        amount_inr = round(amount * rates[currency], 2)
        if amount_inr != amount_inr or amount_inr == inf or amount_inr == -inf:
            continue
        if amount_inr == 0:
            amount_inr = 0.0

        key = (iso_date, description, f'{amount_inr:.2f}')
        if key in seen:
            continue
        seen.add(key)
        parsed.append((iso_date, description, amount_inr))

    parsed.sort(key=lambda row: (row[0], -abs(row[2])))
    return [
        {'date': iso_date, 'description': description, 'amount_inr': amount_inr}
        for iso_date, description, amount_inr in parsed
    ]

def parse_ledger(text):
    import re
    import math
    from datetime import date

    rates = {"INR": 1.0, "USD": 83.5, "EUR": 90.25}
    months = {
        "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
        "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12
    }
    month_alt = "|".join(months)

    date_re = re.compile(
        r"^\s*(?:"
        r"(?P<d1>\d{1,2})/(?P<m1>\d{1,2})/(?P<y1>\d{4})"
        r"|(?P<y2>\d{4})-(?P<m2>\d{1,2})-(?P<d2>\d{1,2})"
        r"|(?P<d3>\d{1,2})\s+(?P<mon3>" + month_alt + r")\s+(?P<y3>\d{4})"
        r"|(?P<mon4>" + month_alt + r")\s+(?P<d4>\d{1,2})\s*,\s*(?P<y4>\d{4})"
        r")\s*,\s*(?P<rest>.*)$",
        re.IGNORECASE,
    )

    dr_re = re.compile(r"^(?P<body>.*?)\s*DR$", re.IGNORECASE)
    amount_re = re.compile(r"(?:\d+(?:,\d+)*(?:\.\d+)?|\.\d+)")
    symbols = ("₹", "$", "€")

    def strip_quotes(s):
        s = s.strip()
        if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
            s = s[1:-1].strip()
        return s

    def strip_symbol(s):
        s = s.strip()
        if s and s[0] in symbols:
            return s[1:].lstrip(), True
        return s, False

    def parse_amount(amount_str, currency):
        s = strip_quotes(amount_str)
        negative = False

        m = dr_re.match(s)
        if m:
            negative = True
            s = strip_quotes(m.group("body"))

        s, symbol_removed = strip_symbol(s)

        if s.startswith("(") and s.endswith(")"):
            negative = True
            s = strip_quotes(s[1:-1])
            s, symbol_removed_inside = strip_symbol(s)
            if symbol_removed and symbol_removed_inside:
                return None

        s = strip_quotes(s)

        if not amount_re.fullmatch(s):
            return None

        try:
            value = float(s.replace(",", ""))
        except (ValueError, OverflowError):
            return None

        if not math.isfinite(value):
            return None

        if negative:
            value = -value

        converted = value * rates[currency]
        if not math.isfinite(converted):
            return None

        amount_inr = round(converted, 2)
        if amount_inr == 0:
            amount_inr = 0.0
        return amount_inr

    def normalize_date(m):
        try:
            if m.group("y1") is not None:
                day = int(m.group("d1"))
                month = int(m.group("m1"))
                year = int(m.group("y1"))
            elif m.group("y2") is not None:
                year = int(m.group("y2"))
                month = int(m.group("m2"))
                day = int(m.group("d2"))
            elif m.group("y3") is not None:
                day = int(m.group("d3"))
                month = months[m.group("mon3").capitalize()]
                year = int(m.group("y3"))
            else:
                day = int(m.group("d4"))
                month = months[m.group("mon4").capitalize()]
                year = int(m.group("y4"))

            return date(year, month, day).isoformat()
        except (ValueError, KeyError, TypeError, AttributeError):
            return None

    def split_description_amount(left):
        s = left.lstrip()

        if s.startswith('"'):
            i = 1
            n = len(s)
            chars = []
            closed = False

            while i < n:
                ch = s[i]
                if ch == '"':
                    if i + 1 < n and s[i + 1] == '"':
                        chars.append('"')
                        i += 2
                        continue
                    closed = True
                    i += 1
                    break
                chars.append(ch)
                i += 1

            if not closed:
                return None

            description = "".join(chars).strip()

            while i < n and s[i].isspace():
                i += 1

            if i >= n or s[i] != ",":
                return None

            return description, s[i + 1:].strip()

        parts = left.split(",", 1)
        if len(parts) != 2:
            return None

        return parts[0].strip(), parts[1].strip()

    rows = []
    seen = set()

    for line in text.splitlines():
        if not line.strip():
            continue

        m = date_re.match(line)
        if not m:
            continue

        iso_date = normalize_date(m)
        if iso_date is None:
            continue

        rest = m.group("rest")
        left, sep, currency = rest.rpartition(",")
        if not sep:
            continue

        currency = currency.strip()
        if currency not in rates:
            continue

        parsed = split_description_amount(left)
        if parsed is None:
            continue

        description, amount_str = parsed
        amount_inr = parse_amount(amount_str, currency)
        if amount_inr is None:
            continue

        key = (iso_date, description, amount_inr)
        if key in seen:
            continue

        seen.add(key)
        rows.append({
            "date": iso_date,
            "description": description,
            "amount_inr": amount_inr
        })

    rows.sort(key=lambda r: (r["date"], -abs(r["amount_inr"])))
    return rows

