        (re.compile(r"^([0-9]{4})-([0-9]{1,2})-([0-9]{1,2})"), "ymd"),
        (re.compile(r"^([0-9]{1,2})\s+([A-Za-z]{3})\s+([0-9]{4})"), "dmon"),
        (re.compile(r"^([A-Za-z]{3})\s+([0-9]{1,2})\s*,\s*([0-9]{4})"), "mond"),
    ]

    number_re = re.compile(
        r"^(?:[0-9]{1,3}(?:,[0-9]+)*(?:\.[0-9]+)?|[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$"
    )

    def parse_date(match, kind):
        try:
            if kind == "dmy":
                day = int(match.group(1))
                month = int(match.group(2))
                year = int(match.group(3))
            elif kind == "ymd":
                year = int(match.group(1))
                month = int(match.group(2))
                day = int(match.group(3))
            elif kind == "dmon":
                day = int(match.group(1))
                month = months.get(match.group(2).lower())
                year = int(match.group(3))
                if month is None:
                    return None
            else:
                month = months.get(match.group(1).lower())
                day = int(match.group(2))
                year = int(match.group(3))
                if month is None:
                    return None

            return _date(year, month, day).isoformat()
        except Exception:
            return None

    def parse_description_and_rest(s):
        i = 0
        n = len(s)

        while i < n and s[i].isspace():
            i += 1

        if i >= n:
            return None

        if s[i] == '"':
            i += 1
            parts = []
            closed = False

            while i < n:
                ch = s[i]
                if ch == '"':
                    if i + 1 < n and s[i + 1] == '"':
                        parts.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    parts.append(ch)
                    i += 1

            if not closed:
                return None

            description = "".join(parts).strip()

            while i < n and s[i].isspace():
                i += 1

            if i >= n or s[i] != ",":
                return None

            return description, s[i + 1:]

        comma = s.find(",", i)
        if comma == -1:
            return None

        description = s[i:comma].strip()
        return description, s[comma + 1:]

    def parse_amount(s):
        s = s.strip()
        if not s:
            return None

        negative = False
        removed_suffix = False
        removed_symbol = False
        removed_parens = False

        while True:
            t = s.strip()
            if not t:
                s = t
                break

            if not removed_suffix and t.upper().endswith("DR"):
                negative = True
                s = t[:-2].strip()
                removed_suffix = True
                continue

            if not removed_symbol and t[0] in symbols:
                s = t[1:].strip()
                removed_symbol = True
                continue

            if not removed_parens and len(t) >= 2 and t.startswith("(") and t.endswith(")"):
                negative = True
                s = t[1:-1].strip()
                removed_parens = True
                continue

            s = t
            break

        if not s:
            return None

        if not number_re.match(s):
            return None

        try:
            value = float(s.replace(",", ""))
        except (ValueError, OverflowError):
            return None

        if value != value or value == float("inf") or value == float("-inf"):
            return None

        if negative:
            value = -value

        return value

    records = []
    seen = set()

    for raw_line in text.splitlines():
        line = raw_line.strip().lstrip("\ufeff").strip()
        if not line:
            continue

        parsed_date = None
        after_date = None

        for pattern, kind in date_patterns:
            match = pattern.match(line)
            if match is None:
                continue

            iso_date = parse_date(match, kind)
            if iso_date is None:
                continue

            rest = line[match.end():].lstrip()
            if not rest.startswith(","):
                continue

            parsed_date = iso_date
            after_date = rest[1:]
            break

        if parsed_date is None:
            continue

        parsed = parse_description_and_rest(after_date)
        if parsed is None:
            continue

        description, remainder = parsed

        if "," not in remainder:
            continue

        amount_field, currency_field = remainder.rsplit(",", 1)
        currency = currency_field.strip()

        if currency not in rates:
            continue

        amount = parse_amount(amount_field)
        if amount is None:
            continue

        try:
            amount_inr = round(amount * rates[currency], 2)
        except Exception:
            continue

        if amount_inr != amount_inr or amount_inr == float("inf") or amount_inr == float("-inf"):
            continue

        if amount_inr == 0:
            amount_inr = 0.0

        key = (parsed_date, description, amount_inr)
        if key in seen:
            continue

        seen.add(key)
        records.append({
            "date": parsed_date,
            "description": description,
            "amount_inr": amount_inr,
        })

    records.sort(key=lambda row: (row["date"], -abs(row["amount_inr"])))
    return records

class LRUCache:
    def __init__(self, capacity, ttl):
        self.capacity = capacity
        self.ttl = ttl
        self._data = {}     # key -> (value, stored_time)
        self._order = []    # least-recently-used first

    def _expired(self, key, now):
        if key not in self._data:
            return True
        return now - self._data[key][1] > self.ttl

    def _purge(self, now):
        expired = [k for k in self._data if self._expired(k, now)]
        for k in expired:
            del self._data[k]
        self._order = [k for k in self._order if k in self._data]

    def put(self, key, value, now):
        if self.capacity <= 0:
            return

        if key in self._data:
            self._data[key] = (value, now)
            while key in self._order:
                self._order.remove(key)
            self._order.append(key)
            return

        if len(self._data) >= self.capacity:
            self._purge(now)

        if len(self._data) >= self.capacity:
            victim = None
            while self._order:
                candidate = self._order.pop(0)
                if candidate in self._data:
                    victim = candidate
                    break
            if victim is not None:
                del self._data[victim]
            elif self._data:
                victim = next(iter(self._data))
                del self._data[victim]

        while key in self._order:
            self._order.remove(key)
        self._data[key] = (value, now)
        self._order.append(key)

    def get(self, key, now):
        if key not in self._data:
            return None

        if self._expired(key, now):
            return None

        while key in self._order:
            self._order.remove(key)
        self._order.append(key)
        return self._data[key][0]

    def size(self, now):
        return sum(1 for _, stored in self._data.values() if now - stored <= self.ttl)

