class LRUCache:
    def __init__(self, capacity, ttl):
        self.capacity = capacity
        self.ttl = ttl
        self._data = {}
        self._order = []

    def _expired(self, key, now):
        return now - self._data[key][1] > self.ttl

    def _purge(self, now):
        for k in list(self._data.keys()):
            if self._expired(k, now):
                del self._data[k]

        self._order = [k for k in self._order if k in self._data]

        present = set(self._order)
        for k in self._data:
            if k not in present:
                self._order.append(k)
                present.add(k)

    def _touch(self, key):
        self._order = [k for k in self._order if k != key]
        self._order.append(key)

    def put(self, key, value, now):
        if self.capacity <= 0:
            return

        if key in self._data:
            self._data[key] = (value, now)
            self._touch(key)
            return

        if len(self._data) >= self.capacity:
            self._purge(now)

        while len(self._data) >= self.capacity:
            if self._order:
                victim = self._order.pop(0)
                if victim in self._data:
                    del self._data[victim]
            elif self._data:
                victim = next(iter(self._data))
                del self._data[victim]
            else:
                break

        self._data[key] = (value, now)
        self._touch(key)

    def get(self, key, now):
        if key not in self._data:
            return None

        if self._expired(key, now):
            del self._data[key]
            self._order = [k for k in self._order if k != key]
            return None

        value = self._data[key][0]
        self._touch(key)
        return value

    def size(self, now):
        return sum(1 for k in self._data if not self._expired(k, now))

