def split_bill(amounts, n):
    from decimal import Decimal

    n = int(n)
    items = []
    max_scale = 0

    for amount in amounts:
        if isinstance(amount, str):
            amount = amount.strip().replace("_", "")

        d = Decimal(amount)
        t = d.as_tuple()

        value = 0
        for digit in t.digits:
            value = value * 10 + digit

        exponent = t.exponent
        if exponent >= 0:
            value *= 10 ** exponent
            scale = 0
        else:
            scale = -exponent

        if t.sign:
            value = -value

        if value == 0:
            continue

        while scale > 0 and value % 10 == 0:
            value //= 10
            scale -= 1

        items.append((value, scale))
        if scale > max_scale:
            max_scale = scale

    total_scaled = 0
    for value, scale in items:
        if scale < max_scale:
            value *= 10 ** (max_scale - scale)
        total_scaled += value

    if total_scaled == 0:
        total_cents = 0
    else:
        denominator = 10 ** max_scale
        numerator = total_scaled * 100
        quotient, remainder = divmod(numerator, denominator)

        if remainder * 2 > denominator or (remainder * 2 == denominator and quotient % 2 != 0):
            quotient += 1

        total_cents = quotient

    base_cents, extra_cents = divmod(total_cents, n)

    parts = []
    for i in range(n):
        cents = base_cents + (1 if i < extra_cents else 0)

        sign = "-" if cents < 0 else ""
        if cents < 0:
            cents = -cents

        parts.append(f"{sign}{cents // 100}.{cents % 100:02d}")

    return parts

def split_bill(amounts, n):
    from decimal import Decimal

    parsed = []
    max_frac = 0
    any_nonzero = False

    for amount in amounts:
        t = Decimal(str(amount).strip()).as_tuple()

        coeff = 0
        for digit in t.digits:
            coeff = coeff * 10 + digit

        if coeff:
            any_nonzero = True

        exp = t.exponent
        if exp < 0 and -exp > max_frac:
            max_frac = -exp

        parsed.append((t.sign, coeff, exp))

    if not any_nonzero:
        total_cents = 0
    else:
        scale = 10 ** max_frac
        factors = {}
        total_units = 0

        for sign, coeff, exp in parsed:
            if coeff == 0:
                continue

            factor = factors.get(exp)
            if factor is None:
                if exp >= 0:
                    factor = scale * (10 ** exp)
                else:
                    factor = scale // (10 ** (-exp))
                factors[exp] = factor

            units = coeff * factor
            if sign:
                total_units -= units
            else:
                total_units += units

        if total_units < 0:
            total_sign = -1
            abs_units = -total_units
        else:
            total_sign = 1
            abs_units = total_units

        q, r = divmod(abs_units * 100, scale)

        # Banker's rounding (ROUND_HALF_EVEN)
        twice = r * 2
        if twice > scale or (twice == scale and q % 2 == 1):
            q += 1

        total_cents = total_sign * q

    base, extra = divmod(total_cents, n)
    parts = []

    for i in range(n):
        cents = base + (1 if i < extra else 0)
        abs_cents = abs(cents)
        sign_str = "-" if cents < 0 else ""
        parts.append(f"{sign_str}{abs_cents // 100}.{abs_cents % 100:02d}")

    return parts

def split_bill(amounts, n):
    from decimal import Decimal

    terms = []
    min_exp = 0

    for s in amounts:
        if isinstance(s, str):
            s = s.strip()

        tup = Decimal(s).as_tuple()
        digits = tup.digits
        exp = tup.exponent

        trim = 0
        for digit in reversed(digits):
            if digit == 0:
                trim += 1
            else:
                break

        if trim:
            digits = digits[:-trim]
            exp += trim

        coeff = 0
        for digit in digits:
            coeff = coeff * 10 + digit

        if tup.sign:
            coeff = -coeff

        if coeff == 0:
            exp = 0

        terms.append((coeff, exp))
        if exp < min_exp:
            min_exp = exp

    scale_exp = min_exp if min_exp < 0 else 0
    denominator = 10 ** (-scale_exp)

    total_units = 0
    for coeff, exp in terms:
        total_units += coeff * (10 ** (exp - scale_exp))

    numerator = total_units * 100
    sign = -1 if numerator < 0 else 1

    q, r = divmod(abs(numerator), denominator)
    twice_r = r * 2

    if twice_r > denominator or (twice_r == denominator and q % 2 == 1):
        q += 1

    total_cents = sign * q

    base, leftover = divmod(total_cents, n)
    parts = []

    for i in range(n):
        cents = base + (1 if i < leftover else 0)

        if cents < 0:
            abs_cents = -cents
            parts.append(f"-{abs_cents // 100}.{abs_cents % 100:02d}")
        else:
            parts.append(f"{cents // 100}.{cents % 100:02d}")

    return parts

def truncate_graphemes(s, n):
    import unicodedata

    if n == 0:
        return s if s == "" else "..."

    category = unicodedata.category
    zwj = "\u200d"

    clusters = 0
