            clusters = 1
            expect = (ch == zwj)
        elif ch == zwj:
            expect = True
        elif category(ch) == "Mn":
            if expect:
                expect = False
        else:
            if expect:
                expect = False
            else:
                if clusters == n:
                    return s[:i] + "..."
                clusters += 1

    return s

